# Load packages
library(Biostrings)
library(dplyr)
library(readr)

# Define inputs
# Gene-level co-expression network statistics
coexpression_file <- file.path(
  "data",
  "external",
  "coexpression",
  "arabidopsis_coexpression_metrics.rds"
)

# Gene-level tissue-specificity data included in the repository
tau_file <- file.path(
  "data",
  "external",
  "tissue_specificity",
  "arabidopsis_tissue_specificity_tau.rds"
)

# Per-gene GWAS trait table generated by 02_build_gene_trait_effects.R.
# Each row represents a gene with at least one retained GWAS association.
gwas_file <- file.path(
  "results",
  "gene_trait_table.csv"
)

# TAIR10 protein FASTA used to define the background gene set.
# IMPORTANT: This file is not included in the repository. Update the path below to its location on your computer.
protein_file <- "/path/to/Arabidopsis_thaliana.TAIR10.pep.all.fa"

# Load data
coexpression_data <- readRDS(
  coexpression_file
)

tau_data <- readRDS(
  tau_file
)

gwas_data <- read_csv(
  gwas_file,
  show_col_types = FALSE
)

proteins <- readAAStringSet(
  protein_file
)

# Define the background gene set
# Extract transcript identifiers from the TAIR10 protein FASTA headers.
protein_ids <- names(
  proteins
)

# Remove transcript suffixes to obtain TAIR10 gene identifiers.
background_genes <- sub(
  "\\.[0-9]+.*$",
  "",
  protein_ids
)

background_genes <- unique(
  background_genes
)

# Identify co-expression and GWAS gene sets
# Genes represented in the co-expression network.
coexpression_genes <- unique(
  coexpression_data$TAIR_gene
)

# Genes with at least one retained GWAS association.
gwas_genes <- unique(
  gwas_data$gene
)


# Test co-expression network representation 
# Construct a gene-level table using the TAIR10 protein-coding gene set as the background.
coexpression_test_data <- data.frame(
  gene = background_genes
)

# Mark whether each background gene is represented in the co-expression network and whether it has at least one GWAS hit.
coexpression_test_data <- coexpression_test_data %>%
  mutate(
    in_coexpression_network = gene %in% coexpression_genes,
    has_gwas_hit = gene %in% gwas_genes
  )

# Create a 2 x 2 contingency table.
coexpression_table <- table(
  Coexpression_network = coexpression_test_data$in_coexpression_network,
  GWAS_hit = coexpression_test_data$has_gwas_hit
)

coexpression_table

# Compare GWAS-hit frequencies inside and outside the co-expression network using Fisher's exact test.
coexpression_fisher_test <- fisher.test(
  coexpression_table
)

coexpression_fisher_test

# Calculate the proportion of genes with a GWAS hit inside the network.
coexpression_gwas_proportion <- mean(
  coexpression_test_data$has_gwas_hit[
    coexpression_test_data$in_coexpression_network
  ]
)

coexpression_gwas_proportion

# Calculate the proportion of genes with a GWAS hit outside the network.
noncoexpression_gwas_proportion <- mean(
  coexpression_test_data$has_gwas_hit[
    !coexpression_test_data$in_coexpression_network
  ]
)

noncoexpression_gwas_proportion

# Test association between tissue specificity and GWAS detection
# Retain one row per gene with its GWAS-hit status.
gwas_status <- gwas_data %>%
  distinct(
    gene
  ) %>%
  mutate(
    has_gwas_hit = TRUE
  )

# Standardize the gene identifier column name in the tau dataset.
tau_data <- tau_data %>%
  rename(
    gene = TAIR_gene
  )

# Retain all genes represented in the tissue-specificity dataset and attach GWAS-hit status.
tau_merged <- tau_data %>%
  left_join(
    gwas_status,
    by = "gene"
  ) %>%
  mutate(
    has_gwas_hit = if_else(
      is.na(has_gwas_hit),
      FALSE,
      has_gwas_hit
    )
  )

# Remove genes without a tissue-specificity estimate.
tau_merged_clean <- tau_merged %>%
  filter(
    !is.na(tau_mean)
  )

# Fit a binomial logistic regression.
# The response indicates whether a gene has at least one GWAS hit. The predictor is tissue specificity measured using tau_mean.
tau_model <- glm(
  has_gwas_hit ~ tau_mean,
  data = tau_merged_clean,
  family = "binomial"
)

summary(
  tau_model
)

# Calculate mean tau separately for genes with and without a GWAS hit.
mean_tau_by_gwas_status <- tau_merged_clean %>%
  group_by(
    has_gwas_hit
  ) %>%
  summarise(
    mean_tau = mean(
      tau_mean,
      na.rm = TRUE
    ),
    n_genes = n(),
    .groups = "drop"
  )

mean_tau_by_gwas_status

# Convert logistic-regression coefficients to odds ratios.
tau_odds_ratios <- exp(
  coef(
    tau_model
  )
)

tau_odds_ratios

# Calculate 95% confidence intervals for the odds ratios.
tau_odds_ratio_confidence_intervals <- exp(
  confint(
    tau_model
  )
)

tau_odds_ratio_confidence_intervals
